effect.shader:
vec3  sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN. Every lookup into the source goes through here, which is what
// pins the quantiser to the layer's own pixels instead of the frame.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }

// Recursive Bayer lattice. bayer2 is the 2x2 seed, bayer4 doubles it, bayer8
// doubles that again - 8x8 is the classic print screen and reads as grain
// rather than as a checkerboard.
float bayer2(vec2 a){ a = floor(a); return fract(a.x * 0.5 + a.y * a.y * 0.75); }
float bayer4(vec2 a){ return bayer2(a * 0.5) * 0.25 + bayer2(a); }
float bayer8(vec2 a){ return bayer4(a * 0.5) * 0.25 + bayer2(a); }

vec2 rot2(vec2 p, float a){ float c = cos(a); float s = sin(a); return vec2(p.x * c - p.y * s, p.x * s + p.y * c); }

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

// Pixels arrive premultiplied. Undo that for the colour work, redo it at the
// very end - grading premultiplied rgb would crush anything semi-transparent.
float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

// ---- tone stage ---------------------------------------------------------
vec3 c = sat3v(sc * pow(2.0, exposure));
c = sat3v((c - vec3(0.5)) * (1.0 + contrast) + vec3(0.5));
c = pow(max(c, vec3(0.0)), vec3(1.0 / max(gamma, 0.05)));
float l = lum(c);
c = mix(vec3(l), c, max(saturation, 0.0));

// ---- level counts -------------------------------------------------------
float lv   = max(levels, 2.0);
float lvl  = max(lv, 2.0);
// Channel Spread tilts the level count per channel, so R/B land on different
// step boundaries and the bands separate into colour fringes.
vec3  lvc  = max(vec3(lv) * (vec3(1.0) + vec3(-0.5, 0.0, 0.5) * channelSpread * 2.0), vec3(2.0));

float patS = ditherScale * max(acLayerSize.y, 1.0) * 0.06;
vec2  pat  = lp * patS;

vec3 q = c;
if (quantMode <= 0){
// Channel Levels - the plain quantiser.
q = floor(c * lvc + vec3(0.5)) / lvc;
} else if (quantMode <= 1){
// Luma Bands - band the luminance, then put the colour back by ratio. Flat
// areas hold their hue instead of sliding toward grey the way a plain
// per-channel quantise does.
float lq = floor(l * lvl + 0.5) / lvl;
q = sat3v(c * (lq / max(l, 1e-4)));
} else if (quantMode <= 2){
// Ordered Dither - the Bayer threshold is offset by half a step either way, so
// the hard edge between two levels breaks into a stipple.
float d = (bayer8(pat) - 0.5) * ditherAmount / lvl;
q = floor((c + vec3(d)) * lvc + vec3(0.5)) / lvc;
} else if (quantMode <= 3){
// Noise Dither - same idea with a hash. Softer than Bayer, no visible lattice.
float d = (h21(floor(pat)) - 0.5) * ditherAmount / lvl;
q = floor((c + vec3(d)) * lvc + vec3(0.5)) / lvc;
} else if (quantMode <= 4){
// Halftone Dots - one dot per cell, radius driven by darkness, and each cell
// gets its own hash rotation so the screen does not look printed by a machine.
float px   = ditherScale * max(acLayerSize.y, 1.0) / 9.0;
vec2  cell = lp * px;
vec2  cid  = floor(cell);
vec2  f    = fract(cell) - vec2(0.5);
float ang  = radians(dotAngle) + (bayer4(cid) - 0.5) * 1.1;
float r    = length(rot2(f, ang));
float rad  = clamp((1.0 - l) * 0.62 * dotGain, 0.0, 0.72);
float cov  = 1.0 - smoothstep(rad - 0.05, rad + 0.05, r);
q = mix(vec3(1.0), c * 0.30, cov);
} else {
// Riso Offset - two ink passes sampled from opposite corners. Multiplying them
// keeps the darker of the two wherever they disagree, which is what makes the
// misregistration read as a second print run.
float o    = max(ditherScale, 0.25) * 0.014;
vec3  inkA = sat3v(fetchL(lp + vec2( o,  o)).rgb);
vec3  inkB = sat3v(fetchL(lp + vec2(-o, -o)).rgb);
vec3  m1   = floor(inkA * lvc + vec3(0.5)) / lvc;
vec3  m2   = floor(inkB * lvc + vec3(0.5)) / lvc;
q = sat3v(m1 * m2 * 1.7);
}
q = sat3v(q);

// ---- duotone ramp -------------------------------------------------------
float ql   = lum(q);
float bias = clamp((ql - 0.5) * (1.0 + (tintBias - 0.5) * 1.6) + 0.5, 0.0, 1.0);
vec3  ramp = mix(shadowCol.rgb, highlightCol.rgb, bias);
q = mix(q, ramp, tintAmount);

// ---- blend --------------------------------------------------------------
vec3 col  = mix(sc, q, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
